insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('chatgpt-plus','ChatGPT Plus','ChatGPT Plus','ai','chatgpt-plus','Sparkles','الأكثر طلباً',true,false,'نموذج GPT-5 الكامل مع التفكير العميق وتوليد الصور والفيديو والصوت والبرمجة','["نموذج GPT-5 الكامل: وصول لأحدث نسخة من النموذج، شامل وضع «التفكير العميق» للمهام اللي محتاجة تحليل وتفكير خطوة بخطوة.","توليد الصور بالذكاء الاصطناعي: إنشاء صور من نص بسرعة أعلى من النسخة المجانية.","تحليل البيانات والأكواد: رفع ملفات (إكسل، PDF، بيانات) وتحليلها، أو كتابة أكواد برمجية بمساعدة أداة تحليل البيانات المدمجة.","توليد فيديو (Sora): إمكانية محدودة لإنشاء مقاطع فيديو قصيرة من وصف نصي.","الوضع الصوتي: التحدث مع الشات بصوتك وسماع الرد بدل الكتابة.","ذاكرة أوسع: الشات بيفتكر تفاصيل من محادثاتك السابقة وبيبني عليها.","Custom GPTs ومساحات عمل (Projects): عمل نسخة مخصصة من الشات لمهمة معينة، وتنظيم شغلك في مشاريع منفصلة.","أولوية استخدام وقت الزحام، وأول من يجرب أي ميزة جديدة تنزل من OpenAI."]'::jsonb,'مدة الضمان مش متطابقة بين العنوان والوصف الأصليين، يُرجى مراجعة الرقم الصحيح قبل النشر على الموقع.',null,0) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
