insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('gemini-pro','Gemini Pro (Google AI Pro)','Gemini Pro (Google AI Pro)','ai','gemini-pro','Brain','تخزين 5TB مجاناً',true,false,'ذكاء جوجل المتقدم مع 5 تيرابايت مساحة تخزين وتفعيل على إيميلك الشخصي','["نموذج Gemini المتقدم: يجاوب على أي سؤال، يكتب أكواد برمجية، يحلل بيانات معقدة، ويكتب محتوى تسويقي وإبداعي بجودة عالية.","تخزين Google One الضخم: 5 تيرابايت مساحة (بدل الـ15 جيجا العادية) لصورك وملفاتك ورسايل Gmail.","توليد فيديو (Veo): تحويل نص مكتوب لفيديو واقعي بجودة عالية.","NotebookLM: رفع ملفات (PDF، مستندات كبيرة) والحصول على تلخيص لها، مع إمكانية «مناقشة» المحتوى.","تعديل الصور بالذكاء الاصطناعي: عزل الخلفيات وتحسين جودة الصور القديمة بضغطة زرار.","Google Flow: استوديو متكامل لتصميم الصور والفيديوهات من نص.","تكامل داخل Gmail وDrive وDocs وSheets وMeet: مساعد ذكاء اصطناعي مدمج جوه تطبيقات جوجل اليومية.","التفعيل بيكون على إيميلك الشخصي، يعني خصوصية كاملة وبياناتك ليك وبس."]'::jsonb,null,null,1) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
