insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('claude-pro','Claude Pro 5X','Claude Pro 5X','ai','claude-pro','Cpu','حدود استخدام 5X',true,false,'أقوى نماذج البرمجة والتفكير والتحليل الدقيق مع أداة Claude Code و Artifacts','["أحدث نماذج Claude: وصول لأقوى نسخ Claude (Sonnet وOpus) لأي مهمة تفكير أو كتابة أو تحليل.","حدود استخدام أعلى (5X): مساحة استخدام أوسع بكتير من الباقة العادية.","Projects: تنظيم شغلك في مساحات عمل منفصلة بسياق ثابت لكل مشروع.","Artifacts: عرض النتائج (كود، تصميم، جداول) في نافذة تفاعلية جنب المحادثة مباشرة.","Claude Code: أداة برمجة بالذكاء الاصطناعي تشتغل من الـ Terminal لمشاريع برمجية حقيقية.","قدرة عالية على التخطيط والبحث المعمّق: مناسب للمهام المعقدة اللي محتاجة خطوات متسلسلة.","الأنسب لأي حد شغله محتاج تفكير عميق ودقة أعلى من الشات العادي."]'::jsonb,null,null,2) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
