insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('super-grok','Super Grok','Super Grok','ai','super-grok','Zap','سريع وتفاعلي',false,false,'أحدث نماذج Grok مع Grok Imagine لتوليد الصور والفيديو والبحث المعمق DeepSearch','["نموذج Grok الأقوى: أولوية وصول لأحدث إصدار من Grok بسرعة استجابة أعلى من النسخة المجانية.","Grok Imagine: توليد صور وفيديوهات بالذكاء الاصطناعي من وصف نصي.","DeepSearch: بحث عميق وتجميع معلومات من مصادر متعددة بدل البحث العادي.","وضع التفكير العميق (Think Mode): تحليل خطوة بخطوة للمسائل المعقدة.","الوضع الصوتي التفاعلي: التحدث مع Grok بصوتك في محادثة طبيعية.","ذاكرة ومشاريع: الشات بيفتكر سياق محادثاتك، وتقدر تنظم شغلك في مهام منفصلة.","مدة 7 أيام مثالية لتجربة الإمكانيات الكاملة بدون التزام طويل."]'::jsonb,null,null,3) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
