insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('canva-pro','Canva Pro','Canva Pro','design','canva-pro','Image','أفضل قيمة',true,false,'140 مليون عنصر وتصميم، أدوات Magic Switch وتوليد الصور وتفريغ خلفية الفيديو','["مكتبة تصميم ضخمة: أكتر من 140 مليون صورة وفيديو وموسيقى وجرافيك جاهز للاستخدام.","تغيير المقاس بضغطة واحدة (Magic Switch): تحويل نفس التصميم لكل المقاسات (ستوري، بوست، بانر) في ثانية.","أدوات ذكاء اصطناعي: كتابة نصوص (Magic Write)، مسح عناصر من الصورة (Magic Eraser)، توسيع الصورة (Magic Expand)، وتوليد صور من نص (Dream Lab).","إزالة خلفية الفيديو: تصوير مباشر بدون خلفية وبدون شاشة خضراء.","Brand Kit: حفظ ألوان وخطوط وشعار المشروع واستخدامهم في أي تصميم بضغطة.","100 جيجا تخزين سحابي لحفظ التصاميم والملفات.","برامج Affinity البديلة (Photo, Designer, Publisher) مع أدوات ذكاء اصطناعي مدمجة.","مناسبة لأي حد بيصمم محتوى سوشيال ميديا أو تسويقي بشكل يومي."]'::jsonb,null,null,4) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
