insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('adobe-creative-cloud','Adobe Creative Cloud (حساب جاهز)','Adobe Creative Cloud (Ready Account)','design','adobe-creative-cloud','Layers','الحزمة الاحترافية',true,false,'أكثر من 20 برنامج احترافي: فوتوشوب، إليستريتور، بريمير، وأفتر إيفكتس مع خطوط Adobe','["أكتر من 20 برنامج احترافي: فوتوشوب، إليستريتور، بريمير برو، أفتر إيفكتس، إن ديزاين، أكروبات، لايت روم، وأكتر.","آلاف الخطوط الاحترافية من مكتبة Adobe Fonts جاهزة للاستخدام في أي مشروع.","Creative Cloud Libraries: مشاركة الألوان والخطوط والعناصر بين كل المشاريع والبرامج.","Adobe Portfolio وBehance: عرض الأعمال في بورتفوليو احترافي والتواصل مع مجتمع المصممين.","قوالب سوشيال ميديا جاهزة للتعديل السريع.","الباقة دي بتتسلم كحساب جاهز مُفعّل بكل البرامج، مناسبة للمصممين والمونتيرين اللي شغلهم على الديسكتوب."]'::jsonb,null,null,5) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
