insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('adobe-express','Adobe Express/Pro (حساب شخصي)','Adobe Express / Pro (Personal Account)','design','adobe-express','PenTool','تفعيل شخصي',false,false,'تصميم سريع من المتصفح والموبايل وتعديل كامل لملفات PDF مع أدوات التوليد بالذكاء الاصطناعي','["تصميم سريع من المتصفح أو الموبايل: قوالب جاهزة لبوستات السوشيال ميديا والمنشورات التسويقية بدون تحميل برنامج ثقيل.","تعديل وتحرير ملفات PDF: دمج وتقسيم وتحويل وتعديل ملفات PDF بشكل أساسي.","أدوات ذكاء اصطناعي للتصميم: توليد وتعديل صور بالذكاء الاصطناعي داخل نفس الأداة.","قوالب مدفوعة حصرية غير متاحة في النسخة المجانية.","التفعيل بيكون على حسابك الشخصي — مناسبة لمن يحتاج تصميم وتعديل PDF بسرعة من غير برامج ديسكتوب ثقيلة."]'::jsonb,null,null,6) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
