insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('figma-pro','Figma Pro Education','Figma Pro Education','design','figma-pro','Figma','سنتين كاملتين',false,false,'مشاريع غير محدودة، مكتبات الفريق، Dev Mode، وأدوات الذكاء الاصطناعي للتصميم','["ملفات ومشاريع غير محدودة: بدل الـ3 ملفات في النسخة المجانية، اعمل أي عدد من المشاريع.","سجل تعديلات كامل: الرجوع لأي نسخة سابقة من التصميم في أي وقت.","Team Libraries: مشاركة المكونات وتوحيد هوية التصميم بين أعضاء الفريق.","Dev Mode: تحويل التصميم لكود جاهز للمبرمجين مباشرة.","أدوات ذكاء اصطناعي: مساعدة في توليد وتعديل التصميمات (متاحة لمستخدمي التعليم العالي).","خطة تعليمية (Education) بريميوم كاملة بسعر رمزي."]'::jsonb,'البريد وكلمة السر متطابقين مع حساب Hotmail المرتبط — ممنوع تغيير البريد في Figma حفاظًا على الضمان.',null,7) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
