insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('capcut-pro','CapCut Pro','CapCut Pro','video','capcut-pro','Video','صناع المحتوى',true,false,'تصدير دقة 4K، تأثيرات Purple Diamond، تفريغ الخلفية وترجمة الكلام وتتبع الكاميرا','["تصدير بجودة أعلى: إمكانية التصدير بدقة 2K وحتى 4K (حسب الجهاز ونوع المقطع).","قوالب وتأثيرات حصرية (Purple Diamond): فلاتر وانتقالات وخطوط مميزة غير متاحة في النسخة المجانية.","أدوات ذكاء اصطناعي: ترجمة الكلام لنص تلقائيًا، إزالة الخلفية، تتبع الكاميرا، وتوليد صور وفيديو وأفاتار بالذكاء الاصطناعي.","تخزين سحابي إضافي لحفظ المشاريع والمقاطع.","يشتغل على كل الأجهزة: موبايل وكمبيوتر ومتصفح بنفس الحساب."]'::jsonb,'الفرق الدقيق بين نسخة «الاقتصادي» و«المميز» في مدة الـ30 يوم (سعة التخزين أو رصيد أدوات الذكاء الاصطناعي) يتم توضيحه بدقة حسب المتاح من المورد.',null,8) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
