insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('netflix','Netflix','Netflix Premium','entertainment','netflix','Film','حساب خاص',true,false,'حساب خاص بالكامل بجودة 4K، إمكانية إرسال حتى 5 دعوات، وضمان ذهبي 25 يوم','["حساب خاص بالكامل: العميل هو المتحكم الوحيد فيه طول مدة الاشتراك.","جودة عرض عالية: مشاهدة بأفضل جودة متاحة على الحساب (Ultra HD / 4K).","إرسال دعوات: إمكانية إرسال حتى 5 دعوات لمشاهدين إضافيين.","بروفايل مخصص للأطفال يقدر العميل يضيفه للحساب.","تسجيل الدخول عبر Outlook: الدخول بالبريد الإلكتروني المرفق، والحصول على رمز التحقق (OTP) من نفس البريد عند الحاجة.","الضمان: 25 يوم. صلاحية الاشتراك: 30 يوم."]'::jsonb,'ممنوع تغيير كلمة مرور Outlook المرتبط بالحساب — تغييرها يلغي الضمان.',null,9) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
