insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('microsoft-office-365','Microsoft Office 365','Microsoft Office 365','productivity','microsoft-office-365','FileText','سنة كاملة + 1TB',true,false,'وورد، إكسل، باوربوينت مع 1 تيرابايت تخزين ون درايف وحماية متقدمة لمدة سنة كاملة','["برامج أوفيس الكاملة: وورد وإكسيل وباوربوينت وأوت لوك بأحدث إصدار.","تيرابايت تخزين سحابي (OneDrive) لحفظ الملفات ومشاركتها من أي جهاز.","اقتراحات ذكية أثناء الكتابة: تصحيح واقتراحات تصميم داخل وورد وباوربوينت.","قوالب وصور وخطوط جاهزة مدمجة داخل البرامج نفسها.","حماية من الفيروسات: كشف واسترجاع الملفات عند هجوم Ransomware، مع خزنة شخصية محمية بتحقق ثنائي (Personal Vault).","اشتراك سنة كاملة (12 شهر) بحساب جاهز."]'::jsonb,null,null,10) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
