insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('whatsapp-sender','واتساب سندر (WhatsApp Sender)','WhatsApp Bulk Sender','marketing','whatsapp-sender','MessageSquare','حملات تسويقية',true,false,'إرسال رسائل جماعية، شات بوت ذكي، تسخين الحسابات، وجدولة الرسائل وفلترة الأرقام','["رسائل جماعية من عدة أرقام: إرسال لعدد كبير من العملاء دفعة واحدة، مع توزيع الحمل على أكتر من رقم واتساب.","فلترة وإدارة الأرقام: التأكد إن الأرقام مفعّلة على واتساب قبل الإرسال، وتنظيمها في قوائم ومجموعات.","شات بوت ذكي: ردود تلقائية على كلمات مفتاحية، ونظام سؤال وجواب متطور.","جدولة الرسائل لتنفيذها أوتوماتيك في ميعاد محدد.","أدوات الجروبات: استخراج الأعضاء، إضافة أعضاء دفعة واحدة، الانضمام التلقائي، والبحث عن جروبات مستهدفة.","تسخين الحساب (Warmer): نشاط تدريجي يقلل احتمالية الحظر.","تقارير وتحليلات مفصّلة لنسب نجاح وفشل الإرسال."]'::jsonb,null,'طريقة التنفيذ: يتم وضع رقم الهاتف في خانة الرابط عند الطلب، وبعدها يتواصل العميل مع دعم واتساب لتفعيل الاشتراك.',11) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
