insert into public.services (id,name,english_name,category_id,slug,icon_name,badge,featured,is_hidden,short_description,features,note,execution_note,sort_order) values ('egypt-numbers-data','داتا أرقام مصرية (30–45 مليون)','Egypt Phone Numbers Database','marketing','egypt-numbers-data','Database','بيانات 2025-2026',true,false,'قاعدة بيانات ضخمة مصنفة حسب التخصص والمهنة والأنشطة التجارية لحملات الواتساب وSMS','["حجم ضخم: من 30 إلى 45 مليون رقم هاتف داخل مصر.","تصنيف حسب المجال: أطباء، صيادلة، مهندسين، مقاولات، شركات، موارد بشرية، كول سنتر، مطاعم، تجار جملة وقطاعي، عقارات، تسويق، سوشيال ميديا، ومشاهير.","مناسبة لحملات متعددة: واتساب، SMS، مكالمات، إعلانات ممولة، وتسويق مباشر.","محدثة باستمرار (بيانات حية 2025–2026)."]'::jsonb,null,'طريقة التنفيذ: يتم وضع رقم الواتساب في خانة الرابط عند الطلب، وبعدها يتواصل دعم واتساب لتسليم البيانات فوراً.',12) on conflict (id) do update set name=excluded.name,english_name=excluded.english_name,category_id=excluded.category_id,icon_name=excluded.icon_name,badge=excluded.badge,featured=excluded.featured,short_description=excluded.short_description,features=excluded.features,note=excluded.note,execution_note=excluded.execution_note,sort_order=excluded.sort_order;
