insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-chatgpt-gemini','21885','ChatGPT زائد Gemini','ChatGPT Plus + Gemini Pro (إضافة بسعر خاص)','["ChatGPT Plus (شهر كامل مع GPT-5)","Gemini Pro (18 شهر + 5TB مساحة سحابية)"]'::jsonb,881.34,985,null,null,null,65,'باقة الذكاء الخارق',false,'اجمع بين أقوى نموذجين في العالم: أحدث إصدار من ChatGPT للبرمجة والتحليل والتفكير العميق + جوجل Gemini Pro مع 5 تيرابايت مساحة سحابية وتكامل مع تطبيقات جوجل.','["وصول لأحدث نماذج GPT-5 ونماذج Gemini المتقدمة","تخزين سحابي عملاق 5 تيرابايت على إيميلك الشخصي","أدوات توليد وتعديل الصور والفيديو والصوت","توفير خاص ومضمون عند شراء النموذجين معاً"]'::jsonb,0) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-claude-gemini','23164','Claude زائد Gemini','Claude Pro 5X + Gemini Pro (إضافة بسعر خاص)','["Claude Pro 5X (حدود استخدام 5X)","Gemini Pro (18 شهر + 5TB مساحة)"]'::jsonb,835.22,935,null,null,null,65,'باقة المبرمجين',false,'أقوى تركيبة للمبرمجين وصناع المحتوى: دقة وتفكير Claude المذهلة في كتابة الأكواد ومراجعتها مع سرعة وتخزين Gemini Pro الضخم.','["حدود استخدام 5 أضعاف على Claude Sonnet و Opus","تخزين سحابي 5 تيرابايت مع Gemini Pro لمدة 18 شهر","أدوات Claude Code و Artifacts البرمجية المتقدمة","تفعيل شخصي مضمون وآمن"]'::jsonb,1) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-academic-year','23232','باقة السنة الدراسية','Office 365 + Gemini Pro + Canva Pro (سنة)','["Microsoft Office 365 (سنة كاملة)","Gemini Pro (18 شهر مع 5TB)","Canva Pro (سنة كاملة)"]'::jsonb,135.08,330,null,null,null,70,'الأنسب للطلاب والمعلمين',false,'كل ما يحتاجه الطالب والباحث والمعلم في مكان واحد: برامج الأوفيس للأبحاث، وجيميني للتلخيص وإعداد المحتوى، وكانفا بريميوم لتصميم العروض التقديمية.','["حزمة أوفيس كاملة (Word, Excel, PowerPoint) لمدة سنة","مساحة تخزين سحابية 1TB OneDrive + 5TB Google One","أدوات الذكاء الاصطناعي لتلخيص الـ PDF عبر NotebookLM","تصميم العروض والملصقات عبر Canva Pro لمدة سنة كاملة"]'::jsonb,2) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-digital-merchant','23940','باقة التاجر الرقمي','داتا أرقام + واتساب سندر (سنة) + Canva Pro (سنة)','["داتا أرقام مصرية (30-45 مليون رقم)","برنامج واتساب سندر (سنة كاملة)","Canva Pro (سنة كاملة)"]'::jsonb,253.59,450,null,null,null,100,'انطلاقة المبيعات',false,'الحزمة التسويقية المتكاملة لمضاعفة مبيعات متجرك: استهدف العملاء بأحدث داتا مصرية، وأرسل حملاتك عبر واتساب سندر، وصمم إعلاناتك بـ Canva Pro.','["قاعدة بيانات مصرية 30-45 مليون رقم مصنفة حسب النشاط والمهنة","برنامج واتساب سندر لمدة سنة مع الشات بوت وتسخين الأرقام","حساب كانفا برو لتصميم البنرات والمنشورات التسويقية","دعم فني كامل لكيفية تشغيل الحملات"]'::jsonb,3) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-launch-project','24140','ابدأ مشروعك','واتساب سندر (مدى الحياة) + داتا أرقام + Canva Pro (3 سنوات)','["واتساب سندر (مدى الحياة)","داتا أرقام مصرية (30-45 مليون رقم)","Canva Pro (3 سنوات كاملة)"]'::jsonb,304.1,550,null,null,null,120,'الاستثمار الدائم',false,'الباقة الكبرى لأصحاب الشركات والوكالات: ترخيص مدى الحياة لبرنامج واتساب سندر، داتا الأرقام الشاملة، و3 سنوات من اشتراك كانفا برو.','["واتساب سندر ترخيص دائم مدى الحياة بدون تجديد سنوي","داتا العملاء 30-45 مليون رقم محدثة 2025-2026","اشتراك كانفا برو لمدة 3 سنوات كاملة","أعلى قيمة وأكبر توفير مالي متاح"]'::jsonb,4) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.bundles (id,code,name,components,components_list,original_price,price,offer_price,offer_label,offer_ends_at,savings,badge,is_hidden,description,features,sort_order) values ('bundle-freelancer-kit','25339','عدة الفريلانسر','Office 365 + Adobe Express/Pro + Gemini Pro','["Microsoft Office 365 (سنة كاملة)","Adobe Express/Pro (3 شهور تفعيل شخصي)","Gemini Pro (18 شهر)"]'::jsonb,255.75,420,null,null,null,80,'عدة العمل الحر',false,'العدة الأساسية للعمل الحر وإنجاز المهام الاحترافية بسرعة: برامج أوفيس، تصميم سريع وتعديل PDF عبر أدوبي، ومساعد Gemini الذكي.','["برامج أوفيس الأصلية مع مساحة 1 تيرابايت OneDrive","تعديل وتوقيع وتحويل ملفات PDF وتصميم سريع عبر Adobe Express","مساعد Gemini المتقدم لتوليد المحتوى وصياغة المقترحات","تفعيل سهل وسريع لحساباتك"]'::jsonb,5) on conflict (id) do update set code=excluded.code,name=excluded.name,components=excluded.components,components_list=excluded.components_list,original_price=excluded.original_price,price=excluded.price,savings=excluded.savings,badge=excluded.badge,description=excluded.description,features=excluded.features,sort_order=excluded.sort_order;
insert into public.site_settings (id,site_name,site_tagline,instapay_handle,instapay_name,vodafone_cash_number,whatsapp_support_number,banner_text,show_banner,working_hours,welcome_bonus) values (1,'سوق الاشتراكات','بازار الاشتراكات الرقمية الأول في مصر والوطن العربي','souq-subs@instapay','سوق الاشتراكات (محمد علي)','01023456789','201023456789','⚡ تسليم فوري لحسابات ChatGPT Plus و Canva Pro وضمان ذهبي كامل طوال فترة الاشتراك!',true,'خدمة العملاء والتسليم: يومياً من 10 صباحاً إلى 2 صباحاً بتوقيت القاهرة',0) on conflict (id) do nothing;